import {useEffect, useState} from 'react';
import {Routes, Route} from 'react-router-dom';
import MovieList from './MovieList';
import Filter from './Filter';
import MovieDetails from './MovieDetails';

function App() {
  const [movies] = useState([
    {
      id: 1,
      title: "Inception",
      description: "A mind-bending thriller",
      posterURL: "data:image/jpeg;base64,",
      rating: 5,
      trailer: "https://www.youtube.com/embed/YoHD9XEInc0"
    },
    {
      id: 2,
      title: "The Dark Knight",
      description: "A superhero film",
      posterURL: "data:image/jpeg;base64,",
      rating: 4,
      trailer: "https://www.youtube.com/embed/EXeTwQWrcwY"
    },
    {
      id: 3,
      title: "Interstellar",
      description: "A science fiction epic",
      posterURL: "data:image/jpeg;base64,",
      rating: 5,
      trailer: "https://www.youtube.com/embed/zSWdZVtXT7E"
    },
    
    {
      id: 4,
      title: "The Matrix",
      description: "A cyberpunk action film",
      posterURL: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRaR6cBLZcCegMr_Myd52jK0DTmQDSgf0clRLmPpSrOdDt6MEA8GPfsGrqMcYCgk8T5DivIelzDa8Nzln2skdUAqD1pI54vXJ1vvDtUpRBz&s=10",
      rating: 4,
      trailer: "https://www.youtube.com/embed/vKQi3bBA1y8"
    },
    {
      id: 5,
      title: "Who Framed Roger Rabbit",
      description: "A live-action/animated comedy",
      posterURL: "data:image/jpeg;base64,",
      rating: 5,
      trailer: "https://www.youtube.com/embed/6hB3S9bIaco"
    }
  ]);

  const [titleFilter, setTitleFilter] = useState("");
  const [ratingFilter, setRatingFilter] = useState(1);
  const [favorites, setFavorites] = useState([]);
  const [showFavorites, setShowFavorites] = useState(false);

  useEffect(() => {
    localStorage.setItem('favorites', JSON.stringify(favorites));
  }, [favorites]);
  const toggleFavorite = (id) =>{
    setFavorites(prev => prev.includes(id)? prev.filter(favId => favId!== id) : [...prev, id]);
  };
  const filteredMovies = movies.filter(
    (movie) =>
      movie.title.toLowerCase().includes(titleFilter.toLowerCase()) &&
      movie.rating >= ratingFilter
  );
  const moviesToShow = showFavorites
  ?movies.filter(movie => favorites.includes(movie.id)) : filteredMovies;


  return (
    <div style={{backgroundColor: "#A52A2A", color: "white", minHeight: "100vh", padding: "20px", gap: '10px'}}>
            <h1 style={{textAlign: "center", marginBottom: "30px", fontSize: "50px"}}>Movie App</h1>

      <button onClick={() => setShowFavorites(false)}
        style={{
          padding: '12px 24px',
          borderRadius: '8px',
          backgroundColor: !showFavorites? 'white' : 'purple',
          color: !showFavorites? 'purple' : 'white',
          border: '2px solid white',
          borderBottom: showFavorites? '3px solid purple' : 'none',
          fontWeight: 'bold',
          fontSize: '16px',
           marginRight: '10px',
          cursor: 'pointer',
           marginBottom: '30px'
        }}>All Movies</button>
        <button onClick={() => setShowFavorites(true)}
        style={{
          padding: '12px 24px',
          borderRadius: '8px',
          backgroundColor: !showFavorites? 'white' : 'purple',
          color: !showFavorites? 'purple' : 'white',
          border: '2px solid white',
          fontWeight: 'bold',
          cursor: 'pointer'
        }}>
          ❣️ Favorites ({favorites.length})
        </button>
      <Routes>
        <Route
          path="/"
          element={
            <>
            {!showFavorites && (
              <Filter
                setTitleFilter={setTitleFilter}
                setRatingFilter={setRatingFilter}
                ratingFilter={ratingFilter}
              />)}
              {showFavorites && moviesToShow.length ===0? (
                <p style={{ textAlign: 'center', fontSize: '20px'}}>No favorites yet. Go add some</p>
              ) : (  <MovieList movies={moviesToShow} favorites={favorites} toggleFavorite={toggleFavorite} />)}
             
            </>
          }
        />
        <Route path="/movie/:id" element={<MovieDetails movies={movies} favorites={favorites} toggleFavorite={toggleFavorite} />} />
      </Routes>
    </div>
  );
}

export default App;
